{
  "meta": {
    "title": "Portfolio Strategy Specification",
    "date": "2026-02-07",
    "purpose": "Operational manual for portfolio management"
  },
  "objectives": {
    "primary": {
      "goal": "Outperform benchmark over 3-5 years",
      "focus": "Risk-adjusted returns"
    },
    "secondary": [
      "Ability to use leverage without stress",
      "Clear rules for buy, trim and exit",
      "Avoid capital drift"
    ]
  },
  "time_horizons": [
    {
      "period": "1-12 months",
      "type": "Repricing/Cyclical"
    },
    {
      "period": "1-3 years",
      "type": "Structural quality"
    },
    {
      "period": "3-7 years",
      "type": "Compounders"
    },
    {
      "period": "Binary",
      "type": "Options"
    }
  ],
  "capital_structure": {
    "leverage_rule": "Leverage only used for high-probability core holdings",
    "cash_policy": {
      "target_range": "10-20%",
      "minimum": "30000 SEK",
      "role": "Risk control and future optionality"
    }
  },
  "portfolio_roles": {
    "core_allocation": {
      "range": "50-60%",
      "criteria": [
        "Strong balance sheet",
        "Pricing power",
        "Visible monetization"
      ],
      "rule": "Buy on doubt, trim on comfort"
    },
    "satellite_allocation": {
      "range": "25-35%",
      "criteria": [
        "Ongoing improvement",
        "Clear triggers within 6-18 months"
      ],
      "rule": "Always have an exit plan"
    },
    "option_allocation": {
      "range": "5-10%",
      "criteria": [
        "Binary outcome",
        "High uncertainty"
      ],
      "rule": "No leverage, no averaging down"
    }
  },
  "buy_strategy": {
    "principle": "Buy what is right but unpopular",
    "rules": [
      "No more than two buys per week",
      "Do not chase post-report spikes",
      "Prefer red or sideways markets"
    ]
  },
  "trim_exit_strategy": {
    "trim": {
      "condition": "Strong short-term performance without earnings acceleration",
      "action": "Trim 25-50%"
    },
    "exit": {
      "condition": "Full valuation or peak margins",
      "action": "Exit position"
    }
  },
  "valuation_philosophy": {
    "core_idea": "Buy mispriced probability, not cheap multiples"
  },
  "operational_discipline": [
    {
      "activity": "Buying",
      "frequency": "1-3 per month"
    },
    {
      "activity": "Trimming",
      "frequency": "On strength"
    },
    {
      "activity": "Full review",
      "frequency": "Quarterly"
    }
  ],
  "psychology_rules": [
    "Sell when it feels safe",
    "Buy when it feels boring",
    "No position should feel impossible to sell"
  ],
  "core_statement": "You manage probabilities, time and capital velocity – not individual stocks."
}
